async function retryUntil(fn, predicate, { timeout = 1000, interval = 50 } = {}) {
  const deadline = Date.now() + timeout;
  let last;
  while (true) {
    last = await fn();
    if (predicate(last)) return last;
    if (Date.now() >= deadline) throw new Error('Timed out, last value: ' + JSON.stringify(last));
    await new Promise(r => setTimeout(r, interval));
  }
}

function bestSelector(el) {
  if (el['data-cy']) return `[data-cy="${el['data-cy']}"]`;
  if (el['data-test']) return `[data-test="${el['data-test']}"]`;
  if (el.id) return `#${el.id}`;
  return el.tag;
}
